 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Each 2x2 L-triomino is colored by its missing corner; squares are color 1.
    shapes = {
        1: {(0, 0), (0, 1), (1, 0), (1, 1)},
        2: {(0, 1), (1, 0), (1, 1)},  # missing top-left
        3: {(0, 0), (0, 1), (1, 1)},  # missing bottom-left
        4: {(0, 0), (1, 0), (1, 1)},  # missing top-right
    }
    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            for color, shape in shapes.items():
                cells = frozenset((r + dr, c + dc) for dr, dc in shape)
                if cells <= occupied:
                    candidates.append((cells, color))
    by_cell = {cell: [] for cell in occupied}
    for cells, color in candidates:
        for cell in cells:
            by_cell[cell].append((cells, color))

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for cells, color in by_cell[cell]:
            if cells <= remaining:
                rest = solve(remaining - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    tiling = solve(occupied)
    if tiling is None:
        raise ValueError('Foreground cannot be tiled by the demonstrated shapes')
    result = [[0] * w for _ in range(h)]
    for cells, color in tiling:
        for r, c in cells:
            result[r][c] = color
    return result

